<body>
<div id="cap"><b>神奈川沖浪裏</b><span>The Great Wave off Kanagawa - after Hokusai - low poly</span></div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// Palette taken from the print: Prussian blues, foam white, aged-paper beige, ochre hulls.
const P = {
  paper: 0xe9dfc6, deep: 0x1b2f66, mid: 0x2f5d9e, light: 0x7fa8cf,
  pale: 0xbcd4e6, foam: 0xf4f1e8, boat: 0xd8a05e, rower: 0x23407e, snow: 0xf4f1e8
};

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(P.paper);
scene.fog = new THREE.Fog(P.paper, 40, 95);

const camera = new THREE.PerspectiveCamera(46, innerWidth / innerHeight, 0.1, 200);
camera.position.set(4.5, 9.5, 24);
camera.lookAt(-2.5, 3.2, -8);

scene.add(new THREE.HemisphereLight(0xf6efdc, 0x23407e, 1.05));
const sun = new THREE.DirectionalLight(0xfff3d6, 1.1);
sun.position.set(-6, 12, 8);
scene.add(sun);

// ---- Sea height field: rolling swells + the great wave ridge + right swell ----
function seaH(x, z, t) {
  let y = 0;
  y += 0.55 * Math.sin(x * 0.28 + t * 0.9) * Math.sin(z * 0.16 - t * 0.5);
  y += 0.34 * Math.sin(x * 0.5 - z * 0.22 + t * 1.25 + 2.0);
  y += 0.2 * Math.sin(z * 0.6 + t * 1.0 + 1.0);
  // great wave: diagonal ridge, tall at front-left, tapering back
  const bx = x + 7.0, bz = z + 1.0;
  const d = bx * 0.82 - bz * 0.42;                 // signed distance from ridge line
  const along = bx * 0.42 + bz * 0.82;             // along the ridge
  let crest = Math.exp(-d * d * 0.10) * 6.0;
  crest *= 1 / (1 + Math.max(0, along - 4) * 0.35);
  crest *= 1 + 0.10 * Math.sin(along * 1.4 - t * 1.6);
  y += crest;
  // right swell rising to the right edge
  const rd = (x - 9.5) * 0.9 - (z + 3) * 0.3;
  y += Math.exp(-rd * rd * 0.045) * 3.0;
  // foreground swell under the front boat
  const fd = (x - 1.5) * 0.5 - (z - 9) * 0.25;
  y += Math.exp(-fd * fd * 0.05) * 1.7;
  return y;
}

const W = 64, D = 46, SX = 150, SZ = 110;
const seaGeo = new THREE.PlaneGeometry(W, D, SX, SZ);
seaGeo.rotateX(-Math.PI / 2);
seaGeo.translate(0, 0, -6);
const seaPos = seaGeo.attributes.position;
const seaCol = new Float32Array(seaPos.count * 3);
seaGeo.setAttribute('color', new THREE.BufferAttribute(seaCol, 3));
const sea = new THREE.Mesh(seaGeo, new THREE.MeshStandardMaterial({
  vertexColors: true, flatShading: true, roughness: 0.9
}));
scene.add(sea);

const cDeep = new THREE.Color(P.deep), cMid = new THREE.Color(P.mid),
      cLight = new THREE.Color(P.light), cPale = new THREE.Color(P.pale),
      cFoam = new THREE.Color(P.foam), tmp = new THREE.Color();

function colorFor(y, x, z, out) {
  // band the height like woodblock colour plates, foam on crests
  let yc = y;
  const d = (x + 7) * 0.82 - (z + 1) * 0.42;   // great-wave front faces the camera: keep it blue
  if (d > 0) yc -= 1.7;
  if (yc > 5.3) out.copy(cFoam);
  else if (yc > 4.8) out.copy(cPale);
  else if (yc > 3.6) out.copy(cLight);
  else if (yc > 1.4) out.copy(cMid);
  else out.copy(cDeep);
